import{_ as l,C as r,o as i,c as s,j as d,a as e,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const x=JSON.parse('{"title":"MarkdownStream","description":"","frontmatter":{},"headers":[],"relativePath":"components/markdown-stream.md","filePath":"components/markdown-stream.md","lastUpdated":1789206102000}'),h={name:"components/markdown-stream.md"},m={id:"markdownstream",tabindex:"-1"};function b(k,t,u,p,f,g){const n=r("Badge"),a=r("XhDemo");return i(),s("div",null,[d("h1",m,[t[0]||(t[0]=e("MarkdownStream ",-1)),o(n,{type:"info",text:"流式正文"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#markdownstream","aria-label":'Permalink to "MarkdownStream <Badge type="info" text="流式正文" />"'},"​",-1))]),t[3]||(t[3]=c('<p>把已经渲好的 Markdown 块列表投影成带稳定 key 的正文结构，按块的种类分流。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/markdown-stream" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/markdown-stream.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/markdown-stream" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/markdown-stream" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/markdown-stream.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>块列表由宿主用流式渲染器得到，组件只按 key 铺开、按种类分流</p>',4)),o(a,{src:"markdown-stream/01-basic"}),t[4]||(t[4]=d("h2",{id:"示例",tabindex:"-1"},[e("示例 "),d("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),t[5]||(t[5]=d("h3",{id:"流式增长",tabindex:"-1"},[e("流式增长 "),d("a",{class:"header-anchor",href:"#流式增长","aria-label":'Permalink to "流式增长"'},"​")],-1)),t[6]||(t[6]=d("p",null,"只有生长中的那一块每帧重渲，定型的块 key 不变、节点原地留着，选区与滚动位置才保得住",-1)),o(a,{src:"markdown-stream/02-streaming"}),t[7]||(t[7]=d("h3",{id:"代码块交给代码视图",tabindex:"-1"},[e("代码块交给代码视图 "),d("a",{class:"header-anchor",href:"#代码块交给代码视图","aria-label":'Permalink to "代码块交给代码视图"'},"​")],-1)),t[8]||(t[8]=d("p",null,"markdown 块铺 html，代码块拿 source 交出去——照 html 渲会让同一段代码出现两次",-1)),o(a,{src:"markdown-stream/03-code-blocks"}),t[9]||(t[9]=d("h3",{id:"流式光标",tabindex:"-1"},[e("流式光标 "),d("a",{class:"header-anchor",href:"#流式光标","aria-label":'Permalink to "流式光标"'},"​")],-1)),t[10]||(t[10]=d("p",null,"一块都还没来的时候光标就已经在了，caret 设成 false 可以整个关掉",-1)),o(a,{src:"markdown-stream/04-caret"}),t[11]||(t[11]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[12]||(t[12]=d("p",null,"size 换正文字号与块间距，三档共用同一份块列表",-1)),o(a,{src:"markdown-stream/05-size"}),t[13]||(t[13]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>展示 AI 回复的正文，且正文是边生成边显示的。</li><li>正文里混着代码块与公式，需要各自交给专门的组件渲染。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>正文是一次性拿到的静态文档：直接渲染就好，不必经过流式内核。</li><li>只是一段纯文本：用<a href="./typography">排印</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li><strong>组件不解析 Markdown，也不持有渲染器。</strong> 块列表由宿主调 <code>@xihan-ui/markdown</code> 的 <code>createStreamRenderer().render(全文)</code> 得到后传进来；渲染器是有状态的，谁持有谁负责。</li><li>块的 <code>key</code> 是稳定的：生长中的那一块 key 恒定，定型的块 key 不再变化。 框架据此复用同一份 DOM 只改文本，用户每收到一个字都被重建节点的话，选区与滚动位置全丢。</li><li><strong><code>html</code> 只对 markdown 块有效。</strong> 代码块拿 <code>source</code> 交给<a href="./code-view">代码视图</a>， 公式块拿 <code>source</code> 交给宿主自选的公式引擎；不接管的降级结果是把原文当正文显示。</li><li>流式光标是皮肤的 <code>::after</code>，不做成组件。它画在带 <code>data-caret</code> 的那一格上： 正文在长的时候是生长的那一块，一块都还没来的时候是外壳，所以请求刚发出去、 一个字都没到的那一段，页面上也有东西。<code>caret</code> 设成 <code>false</code> 时两处都不发这个属性。</li><li>光标在等第一个字的时候闪，出字之后停在实心：正文自己在动，再闪一下只是噪声。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-markdown-stream&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMarkdownStreamContent</code> <code>XhMarkdownStreamLiveRegion</code> <code>XhMarkdownStreamRoot</code></td></tr><tr><td>组合式函数</td><td><code>useMarkdownStream</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/markdown-stream.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;markdown-stream&quot;</code>：<strong><code>root</code></strong> · <strong><code>content</code></strong> · <code>block</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>announce</code></td><td><code>&#39;off&#39; | &#39;polite&#39; | &#39;assertive&#39;</code></td><td></td><td>播报档位，默认 off——会话级播报区在消息流那一层，别在每条回复里各开一个。</td></tr><tr><td><code>blocks</code></td><td><code>readonly MarkdownBlock[]</code></td><td>是</td><td>已渲染好的块列表。</td></tr><tr><td><code>caret</code></td><td><code>boolean</code></td><td></td><td>画不画流式光标，默认画。设成 false 时 data-caret 一处都不发。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td><td>这一段正文是否仍在增长，只落 data-streaming。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;MarkdownStreamTranslations&gt;</code></td><td></td><td></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMarkdownStreamContent</code></td><td><code>block</code></td><td><code>MarkdownStreamBlockSlotProps</code></td><td></td></tr><tr><td><code>XhMarkdownStreamRoot</code></td><td><code>default</code></td><td><code>MarkdownStreamRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;streaming&#39; | &#39;complete&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useMarkdownStream</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>blocks</code></td><td><code>readonly MarkdownBlock[]</code></td><td></td></tr><tr><td><code>streaming</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>announcement</code></td><td><code>string | undefined</code></td><td>播报文本；announce 为 off、或正文还在增长时为 undefined。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBlockProps</code></td><td><code>(props: { block: MarkdownBlock }) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td></td><td>任何时候</td><td>组件不接管任何按键；块内的链接、代码块各自的停靠点由它们自己提供</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;assertive&#39; | &#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;alert&#39; | &#39;status&#39;</td></tr></tbody></table><ul><li>正文不套 role，也不做成活区——每来一个 token 播报一次会把读屏刷爆。</li><li>要在一段回复写完时播报一句，把 <code>announce</code> 设成 <code>polite</code> 并渲出播报区。 一个会话里只该有一个活区，多开会互相打断。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/markdown-stream.css</code> 按部件选择：<code>[data-scope=&quot;markdown-stream&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-caret</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;streaming&#39; | &#39;complete&#39;</td></tr><tr><td><code>block</code></td><td><code>data-caret</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>block</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>block</code></td><td><code>data-kind</code></td><td>block.kind</td></tr><tr><td><code>block</code></td><td><code>data-lang</code></td><td>block.lang</td></tr><tr><td><code>block</code></td><td><code>data-live</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-markdown-stream-caret-bg</code></td><td><code>block</code><br><code>root</code></td><td><code>background</code></td><td><code>caret</code></td><td><code>--xh-fg-default</code></td><td>markdown-stream 的 block、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-duration</code></td><td><code>root</code></td><td><code>animation</code></td><td><code>caret</code></td><td><code>--xh-caret-duration</code></td><td>markdown-stream 的 root 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-enter-duration</code></td><td><code>block</code></td><td><code>animation</code></td><td><code>caret</code></td><td><code>--xh-motion-duration-enter</code></td><td>markdown-stream 的 block 部件 animation 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-gap</code></td><td><code>block</code><br><code>root</code></td><td><code>margin-inline-start</code></td><td><code>caret</code></td><td><code>0.1em</code></td><td>markdown-stream 的 block、root 部件 margin-inline-start 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-h</code></td><td><code>block</code><br><code>root</code></td><td><code>block-size</code></td><td><code>caret</code></td><td><code>1.05em</code></td><td>markdown-stream 的 block、root 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-radius</code></td><td><code>block</code><br><code>root</code></td><td><code>border-radius</code></td><td><code>caret</code></td><td><code>--xh-shape-inset</code></td><td>markdown-stream 的 block、root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-shift</code></td><td><code>block</code><br><code>root</code></td><td><code>translate</code></td><td><code>caret</code></td><td><code>-0.5px</code></td><td>markdown-stream 的 block、root 部件 translate 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-caret-w</code></td><td><code>block</code><br><code>root</code></td><td><code>inline-size</code></td><td><code>caret</code></td><td><code>--xh-stroke-thick</code></td><td>markdown-stream 的 block、root 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>markdown-stream 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_markdown-stream-font-size</code></td><td>markdown-stream 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_markdown-stream-gap</code></td><td>markdown-stream 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-leading</code></td><td><code>root</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-prose-leading</code></td><td>markdown-stream 的 root 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-markdown-stream-mono</code></td><td><code>block</code></td><td><code>font-family</code></td><td><code>kind=code</code><br><code>kind=math</code></td><td><code>--xh-font-family-mono</code></td><td>markdown-stream 的 block 部件 font-family 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-markdown-stream-caret</code> · <code>xh-markdown-stream-caret-in</code> 随皮肤自带，不引用别处文件里的名字。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>代码块交给<a href="./code-view">代码视图</a>，整段正文放进<a href="./message-feed">消息流</a>的一条消息里。</li><li>逐字吐字的节奏由使用者驱动：<code>@xihan-ui/chat-stream</code> 的 <code>visibleLength</code> 是纯函数， 时间原点与 rAF 循环由持有它的那一方写。</li><li>正文里要嵌行内来源角标、脚注这类节点：用 <code>block</code> 插槽接管那一块自己渲。 组件不往已消毒的 html 里插节点，这条插槽就是留给这类需求的位置。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>块列表整份传进来，别在外面切片：稳定 key 靠的就是整份列表的下标与内容。</li><li>代码块交出去时把 <code>complete</code> 一起带上，代码组件据此决定要不要着色。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>每帧新建一个渲染器：缓存作废，长回复到后面会肉眼可见地卡。</li><li>把代码块的 <code>html</code> 与交给代码组件的那份同时渲出来：同一段代码会出现两次。</li></ul>',49))])}const q=l(h,[["render",b]]);export{x as __pageData,q as default};
